-- Launch zones (docs/OPEN_QUESTIONS.md Q8, answered 2026-11-05): the whole of Makati City, the whole of
-- the City of San Fernando (Pampanga) and the whole of San Marcelino (Zambales).
--
-- Boundaries: PSA/PSGC 3Q 2026 administrative boundaries as published by
-- faeldon/philippines-json-maps (MIT; high-resolution GeoJSON, release checksum verified), simplified
-- in PostGIS to about 5 m. Makati is the city outline minus the ten EMBO barangays (Cembo, Comembo,
-- East Rembo, Pembo, Pitogo, Post Proper Northside, Post Proper Southside, Rizal, South Cembo,
-- West Rembo), which the Supreme Court placed under Taguig; the dataset's barangay list agrees, but its
-- city outline still covered them.
--
-- Fees are the pilot defaults; pricing per zone is revisited in Phase 5. Re-running this migration's
-- statement updates the shapes in place (upsert by slug).

insert into public.zones (name, slug, zone_type, area, base_fee_centavos, per_km_centavos, max_radius_km,
                          is_active, service_hours)
